"""Source-only runtime feasibility benchmark, not an application integration."""
from pathlib import Path
import json,sqlite3,zlib,time,tracemalloc,hashlib,statistics
R=Path('reports/product_recovery_v1_scale500');D=Path('data/product_recovery_v1_scale500');read=lambda p:json.loads(Path(p).read_text(encoding='utf-8-sig'));sha=lambda p:hashlib.sha256(Path(p).read_bytes()).hexdigest()
def main():
 target=R/'runtime_audit';target.mkdir(exist_ok=False);dbpath=target/'source_only.sqlite';conn=sqlite3.connect(dbpath);conn.execute('CREATE TABLE companies(company_id TEXT PRIMARY KEY, case_name TEXT NOT NULL, contacts INTEGER NOT NULL)');conn.execute('CREATE TABLE rosters(company_id TEXT PRIMARY KEY,payload BLOB NOT NULL)');conn.execute('CREATE TABLE metadata(key TEXT PRIMARY KEY,value TEXT NOT NULL)');sizes=[];total_contacts=total_proposals=0;start=time.perf_counter()
 for case in sorted((D/'source_inputs').glob('company_*')):
  view=read(case/'messy.json');contacts=read(case/'contacts.json');cid=view['company_id'];p=R/'predictions_1'/case.name;pred=read(p/'messy_predictions.json');claims=read(p/'messy_claims.json');graph=read(p/'messy_graph.json');payload={'company_id':cid,'contacts':contacts,'documents':view['documents'],'claims':claims,'predictions':pred,'graph':graph,'relationship_status':'Unverified experimental proposals; production publication not approved','calibrated_confidence':None};raw=json.dumps(payload,separators=(',',':')).encode();compressed=zlib.compress(raw,6);conn.execute('INSERT INTO companies VALUES(?,?,?)',(cid,case.name,len(contacts)));conn.execute('INSERT INTO rosters VALUES(?,?)',(cid,compressed));sizes.append({'company_id':cid,'case':case.name,'raw_bytes':len(raw),'compressed_bytes':len(compressed)});total_contacts+=len(contacts);total_proposals+=sum(row['manager_id'] is not None for row in pred)
 meta={'schema_version':'recovery-runtime-audit.1','companies':len(sizes),'contacts':total_contacts,'proposals':total_proposals,'approved_published_edges':0,'view':'messy only','includes_hidden_truth':False,'drop_in_v1_compatible':False};conn.execute('INSERT INTO metadata VALUES(?,?)',('manifest',json.dumps(meta)));conn.commit();conn.close();build_seconds=time.perf_counter()-start;times=[];check_start=time.perf_counter()
 with sqlite3.connect(dbpath.resolve().as_uri()+'?mode=ro',uri=True) as db:
  assert db.execute('PRAGMA integrity_check').fetchone()[0]=='ok'
  for cid,blob in db.execute('SELECT company_id,payload FROM rosters'):
   t=time.perf_counter();obj=json.loads(zlib.decompress(blob));ids={p['employee_id'] for p in obj['contacts']};assert ids=={p['employee_id'] for p in obj['predictions']};assert len(ids)>=100;assert all(p['manager_id'] is None or p['manager_id'] in ids and p['manager_id']!=p['employee_id'] for p in obj['predictions']);assert obj['graph']['verified'] is False;times.append((time.perf_counter()-t)*1000)
  largest=max(sizes,key=lambda x:x['raw_bytes']);blob=db.execute('SELECT payload FROM rosters WHERE company_id=?',(largest['company_id'],)).fetchone()[0];tracemalloc.start();obj=json.loads(zlib.decompress(blob));_,peak=tracemalloc.get_traced_memory();tracemalloc.stop()
 result=meta|{'database_bytes':dbpath.stat().st_size,'database_sha256':sha(dbpath),'build_seconds':build_seconds,'all_company_read_decode_seconds':time.perf_counter()-check_start,'mean_decode_ms':statistics.mean(times),'median_decode_ms':statistics.median(times),'p95_decode_ms':sorted(times)[int(.95*(len(times)-1))],'max_decode_ms':max(times),'largest_company_raw_bytes':largest['raw_bytes'],'largest_company_tracemalloc_peak_bytes':peak,'cache24_peak_upper_estimate_bytes':24*peak,'measurement_limit':'Local read/decode with OS cache, not hosted/cloud cold start or concurrent Streamlit load; no deployment performed','schema_mismatch':['v1 expects observed employee columns, baseline/proposed fields and calibrated confidence for manager_id edges','recovery manager_id means experimental proposal, not approved published line','recovery graph verified=false and contains richer source/claim records; candidate lists are unranked','current UI shows v1 fixed metrics/cohort confidence and must not label recovery as v1 or verified'],'future_safe_requirements':['separate versioned adapter and cohort selector','explicit proposal/publication status; no fabricated per-edge probability','show all unresolved contacts alongside proposed hierarchy','company/employee/source search with exact span/date/family provenance','use only new cohort metrics; preserve v1 reporting separately','treat wrong provider and co-managed errors as limitations, never truth-based runtime filtering']};(target/'MANIFEST.json').write_text(json.dumps(result,indent=2)+'\n');(target/'COMPANY_SIZES.json').write_text(json.dumps(sizes,indent=2)+'\n');print(json.dumps(result,indent=2))
if __name__=='__main__':main()
